"use client";
/* Hiss, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Hiss(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("hiss"); }, []);
  return React.createElement("piix-pal", { "pal": "hiss", ...piixAttrs(props) });
}

export default Hiss;
